    "src/main.rs": "use std::fs::File;\nuse std::io::{self, BufRead};\nuse std::path::Path;\n\npub fn count_file(path: &Path) -> io::Result<(usize, usize, usize)> {\n    let file = File::open(path)?;\n    let mut reader = io::BufReader::new(file);\n\n    let mut line_count = 0;\n    let mut word_count = 0;\n    let mut byte_count = 0;\n\n    for line in reader.lines() {\n        let line = line?;\n        line_count += 1;\n        word_count += line.split_whitespace().count();\n        byte_count += line.len();\n    }\n\n    Ok((line_count, word_count, byte_count))\n}\n\nfn main() {\n    let args: Vec<String> = std::env::args().collect();\n\n    if args.len() != 2 {\n        eprintln!(\"Usage: {} <filename>\", args[0]);\n        std::process::exit(1);\n    }\n\n    let path = Path::new(&args[1]);\n    match count_file(path) {\n        Ok((lines, words, bytes)) => {\n            println!(\"{} {} {}\", lines, words, bytes);\n        }\n        Err(e) => {\n            eprintln!(\"Error reading file: {}\", e);\n            std::process::exit(1);\n        }\n    }\n}\n\n#[cfg(test)]\nmod tests {\n    use super::count_file;\n    use std::io::{Error, ErrorKind};\n    use std::path::Path;\n\n    #[test]\n    fn test_count_file() {\n        let content = b\"Hello\\nWorld\\n\";\n        let temp_file = tempfile::NamedTempFile::new().expect(\"Unable to create temporary file\");\n        std::fs::write(temp_file.path(), content).expect(\"Unable to write to temporary file\");\n\n        let (lines, words, bytes) = count_file(temp_file.path()).expect(\"Error counting file\");\n\n        assert_eq!(lines, 2);\n        assert_eq!(words, 2);\n        assert_eq!(bytes, 11);\n    }\n\n    #[test]\n    fn test_count_file_non_existent() {\n        let path = Path::new(\"non_existent_file.txt\");\n        assert_eq!(count_file(path).unwrap_err().kind(), ErrorKind::NotFound);\n    }\n}"
  }
}
